    /// Install the toolchain
    #[command(about = "Install the toolchain")]
    Install {
        /// Runtime directory path to install RustOwl toolchain
        #[arg(long)]
        path: Option<String>,

        /// Install Rust toolchain only
        #[arg(long)]
        skip_rustowl_toolchain: bool,
    },

    /// Uninstall the toolchain
    #[command(about = "Uninstall the toolchain")]
    Uninstall,
}

fn main() {
    let cli = Cli::parse();

    // Handle --version flag
    if cli.version {
        if cli.quiet > 0 {
            println!("v1.0.0-rc.1");
        } else {
            println!("RustOwl v1.0.0-rc.1");
        }
        return;
    }

    // Handle commands
