            Commands::Clean => {
                // Clean command does nothing
            }
            Commands::Toolchain { command: tc } => {
                match tc {
                    ToolchainCommands::Install {
                        path: _,
                        skip_rustowl_toolchain: _,
                    } => {
                        // Install toolchain
                    }
                    ToolchainCommands::Uninstall => {
                        // Uninstall toolchain
                    }
                }
            }
            Commands::Completions { shell } => {
                let mut cmd = build_cli();
                print_completions(shell, &mut cmd);
            }
        }
        return;
    }

    // When no command is provided and no version flag
    if cli.quiet == 0 {
        println!("RustOwl v1.0.0-rc.1");
        println!("This is an LSP server. You can use --help flag to show help.");
    }
}

fn build_cli() -> clap::Command {
    Cli::command()
}

fn print_completions<G: Generator>(gen: G, cmd: &mut clap::Command) {
    generate(gen, cmd, "rustowl", &mut io::stdout());
}
