use std::env;
use std::process;

const VERSION: &str = "1.0.0-rc.1";

fn print_help() {
    println!("Usage: executable [OPTIONS] [COMMAND]

Commands:
  check        Check availability
  clean        Remove artifacts from the target directory
  toolchain    Install or uninstall the toolchain
  completions  Generate shell completions
  help         Print this message or the help of the given subcommand(s)

Options:
  -V, --version   Print version
  -q, --quiet...  Suppress output
      --stdio     Use stdio to communicate with the LSP server
  -h, --help      Print help");
}

fn print_check_help() {
    println!("Check availability

Usage: executable check [OPTIONS] [path]

Arguments:
  [path]  The path of a file or directory to check availability

Options:
      --all-targets   Run the check for all targets instead of current only
      --all-features  Run the check for all features instead of the current active ones only
  -h, --help          Print help");
}

fn print_clean_help() {
    println!("Remove artifacts from the target directory

Usage: executable clean

Options:
  -h, --help  Print help");
}

fn print_toolchain_help() {
    println!("Install or uninstall the toolchain

Usage: executable toolchain [COMMAND]

Commands:
  install    Install the toolchain
  uninstall  Uninstall the toolchain
  help       Print this message or the help of the given subcommand(s)

Options:
  -h, --help  Print help");
}

fn print_toolchain_install_help() {
    println!("Install the toolchain

Usage: executable toolchain install [OPTIONS]

Options:
      --path <path>             Runtime directory path to install RustOwl toolchain
      --skip-rustowl-toolchain  Install Rust toolchain only
  -h, --help                    Print help");
}

fn print_toolchain_uninstall_help() {
    println!("Uninstall the toolchain

Usage: executable toolchain uninstall

Options:
  -h, --help  Print help");
}

fn print_completions_help() {
    println!("Generate shell completions

Usage: executable completions <SHELL>

Arguments:
  <SHELL>
          The shell to generate completions for

          Possible values:
          - bash:       Bourne Again `SHell` (bash)
          - elvish:     Elvish shell
          - fish:       Friendly Interactive `SHell` (fish)
          - powershell: `PowerShell`
          - zsh:        Z `SHell` (zsh)
          - nushell:    Nushell

Options:
  -h, --help
          Print help (see a summary with '-h')");
}

fn main() {
    let args: Vec<String> = env::args().collect();

    let mut version_flag = false;
    let mut quiet_count = 0;
    let mut stdio_flag = false;
    let mut skip_help = false;
    let mut command: Option<String> = None;
    let mut cmd_args: Vec<String> = Vec::new();

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];

        // Check for help or version first
        if skip_help {
            cmd_args.push(arg.clone());
            i += 1;
            continue;
        }

        if arg == "-V" || arg == "--version" {
            version_flag = true;
        } else if arg == "-h" || arg == "--help" {
            if command.is_none() {
                print_help();
                return;
            } else {
                match command.as_ref().unwrap().as_str() {
                    "check" => print_check_help(),
                    "clean" => print_clean_help(),
                    "toolchain" => print_toolchain_help(),
                    "completions" => print_completions_help(),
                    _ => print_help(),
                }
                return;
            }
        } else if arg == "-q" || arg == "--quiet" {
            quiet_count += 1;
        } else if arg == "--stdio" {
            stdio_flag = true;
        } else if arg.starts_with("--") || arg.starts_with("-") {
            eprintln!("error: unexpected argument '{}' found", arg);
            eprintln!();
            eprintln!("Usage: executable [OPTIONS] [COMMAND]");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            process::exit(2);
        } else if command.is_none() {
            command = Some(arg.clone());
            skip_help = true;
        } else {
            cmd_args.push(arg.clone());
        }

        i += 1;
    }

    // Handle version flag
    if version_flag {
        if quiet_count > 0 {
            println!("v{}", VERSION);
        } else {
            println!("RustOwl v{}", VERSION);
        }
        return;
    }

    // Handle commands
    if let Some(cmd) = command {
        match cmd.as_str() {
            "check" => {
                // Parse check arguments
