fn print_elvish_completions() {
    print!(r#"use builtin;
use path;

set edit:completion:arg-completer[rustowl] = {{|cmd|
    fn spaces {|n|
        repeat $n ' ' | str:join ''
    }
    fn cand {|text desc|
        edit:complex-candidate $text &display-suffix=" ($desc)"
    }
    command = 'rustowl'
    completions = []

    $completions = [
        (cand 'check' 'Check availability')
        (cand 'clean' 'Remove artifacts from the target directory')
        (cand 'completions' 'Generate shell completions')
        (cand 'help' 'Print this message or the help of the given subcommand(s)')
        (cand 'toolchain' 'Install or uninstall the toolchain')
        (cand '-V' 'Print version')
        (cand '--version' 'Print version')
        (cand '-q' 'Suppress output')
        (cand '--quiet' 'Suppress output')
        (cand '-h' 'Print help')
        (cand '--help' 'Print help')
        (cand '--stdio' 'Use stdio to communicate with the LSP server')
    ]

    # Complete subcommands based on what was typed
    words = $cmd | str:split ' '

    for i (range 1 (count $words)) {
        set word = $words[$i]
        if (eq $word 'check') {
            set completions = [
                (cand '-h' 'Print help')
                (cand '--help' 'Print help')
                (cand '--all-targets' 'Run the check for all targets instead of current only')
                (cand '--all-features' 'Run the check for all features instead of the current active ones only')
            ]
            break
        } elif (eq $word 'clean') {
            set completions = [
                (cand '-h' 'Print help')
                (cand '--help' 'Print help')
            ]
            break
        } elif (eq $word 'completions') {
            set completions = [
                (cand 'bash' 'Bourne Again `SHell` (bash)')
                (cand 'elvish' 'Elvish shell')
                (cand 'fish' 'Friendly Interactive `SHell` (fish)')
                (cand 'powershell' '`PowerShell`')
                (cand 'zsh' 'Z `SHell` (zsh)')
                (cand 'nushell' 'Nushell')
                (cand '-h' 'Print help')
                (cand '--help' 'Print help')
            ]
            break
        } elif (eq $word 'toolchain') {
            if (or (eq (count $words) 2) (has-value $words 'help')) {
                set completions = [
                    (cand 'install' 'Install the toolchain')
                    (cand 'uninstall' 'Uninstall the toolchain')
                    (cand 'help' 'Print this message or the help of the given subcommand(s)')
                    (cand '-h' 'Print help')
                    (cand '--help' 'Print help')
                ]
            } elif (eq $word 'install') {
                set completions = [
                    (cand '-h' 'Print help')
                    (cand '--help' 'Print help')
                    (cand '--path' 'Runtime directory path to install RustOwl toolchain')
                    (cand '--skip-rustowl-toolchain' 'Install Rust toolchain only')
                ]
            } elif (eq $word 'uninstall') {
                set completions = [
                    (cand '-h' 'Print help')
                    (cand '--help' 'Print help')
                ]
            }
            break
        }
    }

    put $@completions
}}
"#);
}

