    println!("Generate shell completions

Usage: executable completions <SHELL>

Arguments:
  <SHELL>
          The shell to generate completions for

          Possible values:
          - bash:       Bourne Again `SHell` (bash)
          - elvish:     Elvish shell
          - fish:       Friendly Interactive `SHell` (fish)
          - powershell: `PowerShell`
          - zsh:        Z `SHell` (zsh)
          - nushell:    Nushell

Options:
  -h, --help
          Print help (see a summary with '-h')");
}

fn main() {
    let args: Vec<String> = env::args().collect();

    let mut version_flag = false;
    let mut quiet_count = 0;
    let mut _stdio_flag = false;
    let mut skip_help = false;
    let mut command: Option<String> = None;
    let mut cmd_args: Vec<String> = Vec::new();

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];

        // Check for help or version first
        if skip_help {
            cmd_args.push(arg.clone());
            i += 1;
            continue;
        }

        if arg == "-V" || arg == "--version" {
            version_flag = true;
        } else if arg == "-h" || arg == "--help" {
            if command.is_none() {
                print_help();
                return;
            } else {
                match command.as_ref().unwrap().as_str() {
                    "check" => print_check_help(),
                    "clean" => print_clean_help(),
                    "toolchain" => print_toolchain_help(),
                    "completions" => print_completions_help(),
                    _ => print_help(),
                }
                return;
            }
        } else if arg == "-q" || arg == "--quiet" {
            quiet_count += 1;
        } else if arg == "--stdio" {
            _stdio_flag = true;
        } else if arg.starts_with("--") || arg.starts_with("-") {
            eprintln!("error: unexpected argument '{}' found", arg);
            eprintln!();
            eprintln!("Usage: executable [OPTIONS] [COMMAND]");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            process::exit(2);
        } else if command.is_none() {
            command = Some(arg.clone());
            skip_help = true;
        } else {
            cmd_args.push(arg.clone());
        }

        i += 1;
    }

    // Handle version flag
    if version_flag {
        if quiet_count > 0 {
            println!("v{}", VERSION);
        } else {
            println!("RustOwl v{}", VERSION);
        }
        return;
    }

    // Handle commands
    if let Some(cmd) = command {
        match cmd.as_str() {
            "check" => {
                // Parse check arguments
                let mut help_flag = false;
                let mut _path: Option<String> = None;
                let mut _all_targets = false;
                let mut _all_features = false;

                let mut j = 0;
                while j < cmd_args.len() {
                    let arg = &cmd_args[j];
                    if arg == "-h" || arg == "--help" {
                        help_flag = true;
                    } else if arg == "--all-targets" {
                        _all_targets = true;
                    } else if arg == "--all-features" {
                        _all_features = true;
                    } else if !arg.starts_with("-") {
                        _path = Some(arg.clone());
                    } else {
                        eprintln!("error: unexpected argument '{}' found", arg);
                        eprintln!();
                        eprintln!("Usage: executable check [OPTIONS] [path]");
                        eprintln!();
                        eprintln!("For more information, try '--help'.");
                        process::exit(2);
                    }
                    j += 1;
                }

                if help_flag {
                    print_check_help();
                } else {
                    // Check command functionality (stub)
                    process::exit(1);
                }
            }
            "clean" => {
                // Parse clean arguments
                let mut help_flag = false;

                for arg in &cmd_args {
                    if arg == "-h" || arg == "--help" {
                        help_flag = true;
                    } else {
                        eprintln!("error: unexpected argument '{}' found", arg);
                        eprintln!();
                        eprintln!("Usage: executable clean");
                        eprintln!();
                        eprintln!("For more information, try '--help'.");
                        process::exit(2);
                    }
                }

                if help_flag {
                    print_clean_help();
                }
                // Clean command does nothing
            }
            "toolchain" => {
                if cmd_args.is_empty() {
                    print_toolchain_help();
                    return;
                }

                let subcmd = &cmd_args[0];
                let sub_args = &cmd_args[1..];

                match subcmd.as_str() {
                    "install" => {
                        let mut help_flag = false;
                        let mut _path: Option<String> = None;
                        let mut _skip_rustowl = false;

                        let mut j = 0;
                        while j < sub_args.len() {
                            let arg = &sub_args[j];
                            if arg == "-h" || arg == "--help" {
                                help_flag = true;
                            } else if arg == "--path" {
                                if j + 1 < sub_args.len() {
                                    _path = Some(sub_args[j + 1].clone());
                                    j += 1;
                                }
                            } else if arg == "--skip-rustowl-toolchain" {
                                _skip_rustowl = true;
                            } else {
                                eprintln!("error: unexpected argument '{}' found", arg);
                                eprintln!();
                                eprintln!("Usage: executable toolchain install [OPTIONS]");
                                eprintln!();
                                eprintln!("For more information, try '--help'.");
                                process::exit(2);
                            }
                            j += 1;
                        }

                        if help_flag {
                            print_toolchain_install_help();
                        }
                    }
                    "uninstall" => {
                        let mut help_flag = false;

                        for arg in sub_args {
                            if arg == "-h" || arg == "--help" {
                                help_flag = true;
                            } else {
                                eprintln!("error: unexpected argument '{}' found", arg);
                                eprintln!();
                                eprintln!("Usage: executable toolchain uninstall");
                                eprintln!();
                                eprintln!("For more information, try '--help'.");
                                process::exit(2);
                            }
                        }

                        if help_flag {
                            print_toolchain_uninstall_help();
                        }
                    }
                    "-h" | "--help" | "help" => {
                        print_toolchain_help();
                    }
                    _ => {
                        eprintln!("error: unknown subcommand '{}'", subcmd);
                        eprintln!();
                        eprintln!("Usage: executable toolchain [COMMAND]");
                        eprintln!();
                        eprintln!("For more information, try '--help'.");
                        process::exit(2);
                    }
                }
            }
            "completions" => {
                if cmd_args.is_empty() {
                    eprintln!("error: missing required argument '<SHELL>'");
                    eprintln!();
                    eprintln!("Usage: executable completions <SHELL>");
                    eprintln!();
                    eprintln!("For more information, try '--help'.");
                    process::exit(2);
                }

                let shell = &cmd_args[0];

                // Check for help
                let mut help_flag = false;
                if cmd_args.len() > 1 {
                    for arg in &cmd_args[1..] {
                        if arg == "-h" || arg == "--help" {
                            help_flag = true;
                        }
                    }
                }

                if help_flag {
                    print_completions_help();
                    return;
                }

                match shell.as_str() {
                    "bash" => print_bash_completions(),
                    "fish" => print_fish_completions(),
                    "zsh" => print_zsh_completions(),
                    "powershell" => print_powershell_completions(),
                    "elvish" => print_elvish_completions(),
                    "nushell" => print_nushell_completions(),
                    "-h" | "--help" | "help" => print_completions_help(),
                    _ => {
                        eprintln!("error: invalid value '{}' for '<SHELL>'", shell);
                        eprintln!();
                        eprintln!("  [possible values: bash, elvish, fish, powershell, zsh, nushell]");
                        eprintln!();
                        eprintln!("For more information, try '--help'.");
                        process::exit(2);
                    }
                }
            }
            "help" => {
                if cmd_args.is_empty() {
                    print_help();
                } else {
                    // Handle help for specific commands
                    match cmd_args[0].as_str() {
                        "check" => print_check_help(),
                        "clean" => print_clean_help(),
                        "toolchain" => print_toolchain_help(),
                        "completions" => print_completions_help(),
                        "help" => print_help(),
                        _ => print_help(),
                    }
                }
            }
            "-h" | "--help" => {
                print_help();
            }
            _ => {
                eprintln!("error: unknown subcommand '{}'", cmd);
                eprintln!();
                eprintln!("Usage: executable [OPTIONS] [COMMAND]");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                process::exit(2);
            }
        }
    } else {
        // No command provided
        if quiet_count == 0 {
            println!("RustOwl v{}", VERSION);
            println!("This is an LSP server. You can use --help flag to show help.");
        }
    }
}

fn print_bash_completions() {
    print!(r#"_rustowl() {{
    local i cur prev opts cmd
    COMPREPLY=()
    if [[ "${{BASH_VERSINFO[0]}}" -ge 4 ]]; then
        cur="$2"
    else
        cur="${{COMP_WORDS[COMP_CWORD]}}"
    fi
    prev="$3"
    cmd=""
    opts=""

    for i in "${{COMP_WORDS[@]:0:COMP_CWORD}}"
    do
        case "${{cmd}},${{i}}" in
            ",$1")
                cmd="rustowl"
                ;;
            rustowl,check)
                cmd="rustowl__check"
                ;;
            rustowl,clean)
                cmd="rustowl__clean"
                ;;
            rustowl,completions)
                cmd="rustowl__completions"
                ;;
            rustowl,help)
                cmd="rustowl__help"
                ;;
            rustowl,toolchain)
                cmd="rustowl__toolchain"
                ;;
            rustowl__toolchain,help)
                cmd="rustowl__toolchain__help"
                ;;
            rustowl__toolchain,install)
                cmd="rustowl__toolchain__install"
                ;;
            rustowl__toolchain,uninstall)
                cmd="rustowl__toolchain__uninstall"
                ;;
            *)
                ;;
        esac
    done

    case "${{cmd}}" in
        rustowl)
            opts="-V -q -h --version --quiet --stdio help check clean completions toolchain"
            if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq 1 ]] ; then
                COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
                return 0
            fi
            case "${{prev}}" in
                *)
                    COMPREPLY=()
                    ;;
            esac
            COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
            return 0
            ;;
        rustowl__check)
            opts="-h --help --all-targets --all-features"
            if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq 2 ]] ; then
                COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
                return 0
            fi
            COMPREPLY=( $(compgen -f -- "${{cur}}") )
            return 0
            ;;
        rustowl__clean)
            opts="-h --help"
            if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq 2 ]] ; then
                COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
                return 0
            fi
            COMPREPLY=()
            return 0
            ;;
        rustowl__completions)
            opts="-h --help bash elvish fish powershell zsh nushell"
            if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq 2 ]] ; then
                COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
                return 0
            fi
            COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
            return 0
            ;;
        rustowl__help)
            opts="check clean completions toolchain help"
            if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq 2 ]] ; then
                COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
                return 0
            fi
            COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
            return 0
            ;;
        rustowl__toolchain)
            opts="-h --help install uninstall help"
            if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq 2 ]] ; then
                COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
                return 0
            fi
            case "${{prev}}" in
                *)
                    COMPREPLY=()
                    ;;
            esac
            COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
            return 0
            ;;
        rustowl__toolchain__help)
            opts="install uninstall"
            if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq 3 ]] ; then
                COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
                return 0
            fi
            COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
            return 0
            ;;
        rustowl__toolchain__install)
            opts="-h --help --path --skip-rustowl-toolchain"
            if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq 3 ]] ; then
                COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
                return 0
            fi
            case "${{prev}}" in
                --path)
                    COMPREPLY=($(compgen -f -- "${{cur}}") )
                    return 0
                    ;;
                *)
                    COMPREPLY=()
                    ;;
            esac
            COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
            return 0
            ;;
        rustowl__toolchain__uninstall)
            opts="-h --help"
            if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq 3 ]] ; then
                COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
                return 0
            fi
            COMPREPLY=()
            return 0
            ;;
    esac
}}
complete -o bashdefault -o default -o nospace -F _rustowl rustowl
"#);
}

