            [CompletionResult]::new('-h', '-h', 'ParameterValue', 'Print help'),
            [CompletionResult]::new('--help', '--help', 'ParameterValue', 'Print help')
        )
    }} elseif ($elements[1] -eq 'toolchain') {{
        if ($elements.Count -lt 3 -or ($elements[2] -in @('-h', '--help'))) {{
            $Local:completions += @(
                [CompletionResult]::new('install', 'install', 'ParameterValue', 'Install the toolchain'),
                [CompletionResult]::new('uninstall', 'uninstall', 'ParameterValue', 'Uninstall the toolchain'),
                [CompletionResult]::new('help', 'help', 'ParameterValue', 'Print this message or the help of the given subcommand(s)'),
                [CompletionResult]::new('-h', '-h', 'ParameterValue', 'Print help'),
                [CompletionResult]::new('--help', '--help', 'ParameterValue', 'Print help')
            )
        }} elseif ($elements[2] -eq 'install') {{
            $Local:completions += @(
                [CompletionResult]::new('-h', '-h', 'ParameterValue', 'Print help'),
                [CompletionResult]::new('--help', '--help', 'ParameterValue', 'Print help'),
                [CompletionResult]::new('--path', '--path', 'ParameterValue', 'Runtime directory path to install RustOwl toolchain'),
                [CompletionResult]::new('--skip-rustowl-toolchain', '--skip-rustowl-toolchain', 'ParameterValue', 'Install Rust toolchain only')
            )
        }} elseif ($elements[2] -eq 'uninstall') {{
            $Local:completions += @(
                [CompletionResult]::new('-h', '-h', 'ParameterValue', 'Print help'),
                [CompletionResult]::new('--help', '--help', 'ParameterValue', 'Print help')
            )
        }}
    }}

    return $Local:completions | Where-Object {{ $_.CompletionText -like "$word*" }} |
        Sort-Object -Property CompletionText
}}
"#);
}

