fn main() {
    let args: Vec<String> = env::args().collect();

    let mut version_flag = false;
    let mut quiet_count = 0;
    let mut _stdio_flag = false;
    let mut command: Option<String> = None;
    let mut cmd_args: Vec<String> = Vec::new();

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];

        // Handle short flags bundled together (e.g., -qq, -qV, etc.)
        if arg.starts_with('-') && !arg.starts_with("--") && arg.len() > 2 && !arg.starts_with("-h") {
            // Process each character in the bundled short flags
            let chars: Vec<char> = arg.chars().collect();
            let mut j = 1; // skip the '-'
            while j < chars.len() {
                let ch = chars[j];
                match ch {
                    'q' => quiet_count += 1,
                    'V' => version_flag = true,
                    'h' => {
                        if command.is_none() {
                            print_help();
                            return;
                        } else {
                            match command.as_ref().unwrap().as_str() {
                                "check" => print_check_help(),
                                "clean" => print_clean_help(),
                                "toolchain" => print_toolchain_help(),
                                "completions" => print_completions_help(),
                                _ => print_help(),
                            }
                            return;
                        }
                    }
                    _ => {
