        (cand '-h' 'Print help')
        (cand '--help' 'Print help')
        (cand '--stdio' 'Use stdio to communicate with the LSP server')
    ]

    # Complete subcommands based on what was typed
    words = $cmd | str:split ' '

    for i (range 1 (count $words)) {{
        set word = $words[$i]
        if (eq $word 'check') {{
            set completions = [
                (cand '-h' 'Print help')
