fn print_powershell_completions() {
    print!(r#"using namespace System.Management.Automation
using namespace System.Management.Automation.Language

Register-ArgumentCompleter -CommandName rustowl -ScriptBlock {{
    param($wordToComplete, $commandAst, $cursorPosition)

    $Local:word = $wordToComplete.Replace('"','') # If the argument was quoted, remove the quotes.
    $Local:ast = $commandAst.Extent

    $Local:elements = $ast.Text.Split(@(' ', "`t"), [System.StringSplitOptions]::RemoveEmptyEntries)

    $Local:completions = @()

    # Check if we're completing a subcommand
    if ($elements.Count -lt 2 -or ($elements[1] -in @('-h', '--help', '-V', '--version', '-q', '--quiet', '--stdio'))) {{
        $Local:completions += @(
            [CompletionResult]::new('check', 'check', 'ParameterValue', 'Check availability'),
